def case_html(c: dict) -> str:
    q = "".join(f"<li>{x}</li>" for x in c["q"])
    return (f'<div class="case-mini fade"><div class="meta">{c["tag"]} · 8 минут</div><h4>{c["title"]}</h4>'
            f'<p style="font-size:.94rem;line-height:1.7"><b>Ситуация.</b> {c["sit"]}</p>'
            f'<p class="lab" style="margin-top:8px">Вопросы для решения</p><ol class="step-list">{q}</ol>'
            f'<p style="font-size:.92rem;margin-top:8px"><b>Результат:</b> {c["res"]}</p>'
            f'<p class="lab" style="margin-top:10px">Запрос для практики (копируется целиком)</p>{{{{PROMPT:{c["prompt"]}}}}}'
            f'<details class="details-key" style="margin-top:10px"><summary>Разбор кейса {c["n"]} <span class="hint">откройте после решения</span></summary>'
            f'<div class="body">{c["ans"]}</div></details></div>')


def s12() -> str:
    b = slide(26, "Слайд «Практикум: порядок работы»: вводная 5 минут; четыре кейса и вывод 35 минут; запрос и документ 25 минут; личный чек-лист 20 минут; проверка 5 минут",
              ["Практикум 1.3 рассчитан на отдельные 90 минут. В нашем уроке вы можете использовать его целиком как отдельное занятие или выбирать кейсы для замены практик. Порядок работы: 5 минут — цель и роли; 35 минут — четыре кейса (по 8 минут: 1 на чтение, 3 на решение, 3 на обсуждение, 1 на фиксацию) и общий вывод; 25 минут — подготовка запроса и документа из десяти пунктов; 20 минут — личный чек-лист и три действия; 5 минут — проверка и завершение.",
               "Работать можно индивидуально, в парах или группах по 3–4 человека. В группе распределите роли: исполнитель задачи, руководитель, специалист по защите информации и докладчик. Роли учебные и не означают наличия соответствующих полномочий в реальной организации."],
              takeaway="Цель практикума — принять решение до передачи информации, а не запретить ИИ.")
    b += card("Как устроен практикум: этапы и правила",
              table("Этапы практикума 1.3", ["Этап", "Действие", "Минуты"],
                    [["Вводная часть", "Цель, ограничения, распределение ролей", "5"], ["Часть 1", "Четыре кейса по 8 минут и общий вывод 3 минуты", "35"],
                     ["Часть 2", "Подготовка запроса и документа из десяти пунктов", "25"], ["Часть 3", "Личный чек-лист и план действий", "20"],
                     ["Часть 4", "Проверка результата и завершение", "5"], ["Итого", "Практическое занятие", "90"]])
              + '<p class="q-hint">Все ситуации, реплики и сведения в заданиях вымышлены. Реальные кадровые документы, технические материалы, закрытые показатели, переписка и записи совещаний для выполнения заданий не нужны. ИИ используется только в разрешённой учебной среде; если такого доступа нет, задания выполняются без обращения к сервису. Кейсы 5–7 — для самостоятельной работы или замены одного основного кейса.</p>')
    b += card("Карточка решения кейса (для каждого кейса)",
              '<div class="data-block" id="db-card">Номер кейса: ____\nРабочая цель: какой полезный результат хотел получить сотрудник?\nДанные и риск: какие сведения или действия требуют проверки?\nЧто установлено и что неизвестно: отделите факты условия от предположений.\nРешение сейчас: какое действие нужно выполнить или приостановить?\nБезопасный способ решить задачу: предложите конкретный вариант.\nК кому обратиться и что уточнить: укажите функцию ответственного лица.</div>'
              '<p class="q-hint">На один ответ достаточно 5–7 предложений или коротких пунктов. Скопируйте карточку для каждого кейса.</p>')
    b += "".join(case_html(c) for c in CASES)
    b += card("Общий вывод по кейсам",
              '<p style="font-size:.95rem;line-height:1.75">За 3 минуты сформулируйте <b>одно правило</b>, которое помогает предотвратить ошибку до передачи данных, и <b>одно правило</b> для проверки результата. Обсуждайте учебные ситуации, не раскрывая реальные события из работы подразделений.</p>')
    b += card("Часть 2. Подготовка запроса и документа из десяти пунктов (25 минут)",
              paras(["Выберите один сценарий: <b>1)</b> руководитель готовит пустой шаблон справки о выполнении плана; <b>2)</b> менеджер по качеству составляет общую структуру обсуждения причин отклонений без показателей предприятия; <b>3)</b> проектный менеджер разрабатывает форму протокола; <b>4)</b> специалист по обучению создаёт учебный тест по общему материалу. Во всех вариантах — общие формулировки, пустые поля или придуманные сведения.",
                     "Порядок: 5 минут — выбор задачи и безопасный запрос (готовые запросы U11–U14); 15 минут — заполнение десяти пунктов; 5 минут — взаимная проверка. При работе в группе оформляется один общий документ.",
                     "Фраза «соблюдай конфиденциальность» не делает безопасной загрузку запрещённого материала. Запрос содержит цель, формат результата, разрешённые исходные сведения и пределы ответа."])
              + '<p class="lab" style="margin-top:8px">Образец запроса из практикума</p><div class="data-block" id="db-sample">Подготовь пустой шаблон протокола рабочего совещания. Поля: тема, цель, рассматриваемые вопросы, принятые решения, ответственные роли, срок выполнения, способ проверки. Не подставляй имена, названия организаций, даты, цифры и нормативные требования. Если для решения нужен факт, оставь поле для заполнения. В конце добавь три вопроса автору для проверки полноты протокола.</div>')
    rows = "".join(f'<tr><td class="t">{i}. {t}</td><td>{d}</td></tr>' for i, (t, d) in enumerate(DOC10, 1))
    b += card("Шаблон документа «Предложения по безопасному применению ИИ в подразделении»",
              f'<p style="font-size:.94rem;line-height:1.7">Укажите выбранный учебный сценарий. На каждый пункт — 1–2 предложения. Если внутреннее правило неизвестно, обозначьте, что именно нужно уточнить и у какой функции. Не придумывайте название действующего сервиса, номер локального акта или должность согласующего.</p><div class="fine-table-wrap"><table class="fine-table"><thead><tr><th>Пункт</th><th>Что написать</th></tr></thead><tbody>{rows}</tbody></table></div>'
              '<p class="lab" style="margin-top:10px">Запрос для заготовки документа</p>{{PROMPT:PRD}}')
    b += key("Образец документа из десяти пунктов (сценарий «пустой шаблон управленческой справки»)",
             "<ol>" + "".join(f"<li>{x}</li>" for x in [
                 "<b>Цель.</b> Использовать ИИ для подготовки структуры справки и вопросов автору. Реальные сведения о деятельности подразделения в учебный запрос не включать.",
                 "<b>Данные.</b> Только общая тема, требования к структуре и пустые поля. Для демонстрации — полностью придуманные примеры.",
                 "<b>Ограничения.</b> Исключить персональные данные, закрытые документы, реквизиты договоров, технические параметры и действующие показатели.",
                 "<b>Инструмент.</b> Среда, разрешённая для данного сценария. При отсутствии подтверждения — подготовить шаблон без ИИ и уточнить порядок у ответственной функции.",
                 "<b>Подготовка.</b> Проверить текст и файлы, включая комментарии, исправления и встроенные объекты; вводить специально составленный короткий запрос вместо полного документа.",
                 "<b>Проверка.</b> Автор сверяет результат с целью и требованиями. Неподтверждённые факты и нормы не включаются.",
                 "<b>Полномочия.</b> ИИ не получает возможности автоматически отправить или утвердить справку; реальные данные и решения вносит уполномоченный сотрудник.",
                 "<b>Хранение.</b> Результат сохраняется в разрешённом месте и передаётся установленному кругу получателей; роль ИИ и проверка фиксируются в объёме, предусмотренном процессом.",
                 "<b>Инциденты.</b> При подозрении на ошибочную передачу прекратить действия, сообщить по установленному каналу, следовать указаниям ответственных.",
                 "<b>Согласование.</b> До применения уточнить допустимость у владельца процесса и ответственных за защиту информации; пересматривать при изменении задачи, данных, инструмента или требований."]) + "</ol><p>Формулировки — образец для обсуждения; они требуют применения установленного порядка организации.</p>")
    sc = "".join(f'<p class="lab" style="margin-top:10px">{g}</p><ol class="step-list">' + "".join(f"<li>{i}</li>" for i in items) + "</ol>" for g, items in SELF_CHECK)
    txt = "\n".join(f"{g}\n" + "\n".join(f"— {i}  (да / частично / нужно уточнить / неприменимо)" for i in items) for g, items in SELF_CHECK)
    b += card("Часть 3. Личный чек-лист цифровой безопасности (15 пунктов)",
              '<p style="font-size:.94rem;line-height:1.7">Выделите 8 минут на заполнение, 7 минут на обсуждение общих принципов и 5 минут на план действий. По каждому пункту отметьте один вариант: <b>да / частично / нужно уточнить / неприменимо</b>. Это самооценка привычек и осведомлённости; количество отметок не доказывает защищённость организации. Критичный непрояснённый вопрос нельзя компенсировать положительными ответами в других пунктах.</p>'
              + sc + f'<div class="data-block" id="db-check" hidden>{txt}</div>'
              '<p class="q-hint">В первую очередь уточните пункты 3, 5, 6 и 13 (допустимость обработки, инструменты, доступ помощника, канал сообщения об инциденте). До прояснения не вводите соответствующие рабочие данные. Изменения настроек и установка программ выполняются по принятому в организации порядку.</p>')
    b += card("Три действия после занятия",
              table("Мой план", ["Что уточню или изменю", "Через какую функцию или канал", "Когда проверю результат"], [["____", "____", "____"], ["____", "____", "____"], ["____", "____", "____"]])
              + '<p class="q-hint">Пример: «Уточню допустимость сценария подготовки пустого шаблона справки — через владельца процесса и ответственного за ИБ — до первого использования». Достаточно названия функции; реальные контакты не требуются.</p>')
    b += card("Что сдавать и как оценивается работа",
              paras(["Через разрешённую учебную платформу сдаётся один файл: 1) решения четырёх основных кейсов, включая таблицу исправлений по кейсу 4; 2) предложения из десяти пунктов и пример запроса; 3) короткий вывод из 3–5 предложений. Личный чек-лист остаётся у вас; в работу включается только обобщённый план без сведений о реальных недостатках защиты.",
                     "Критерии (0/1/2 балла, максимум 10): данные и ограничения; первое действие; полезное решение; проверка и полномочия; качество документа. Ориентир — 8–10 баллов. Не принимается решение, предлагающее загрузить закрытый материал в непроверенный сервис, передать пароль, продолжить извлечение чужих данных или скрыть инцидент."])
              + bullets(["Какой результат в вашей работе можно получить от ИИ без передачи исходных документов?", "В каком случае следует сначала уточнить допустимость обработки, даже если сервис знаком?", "Чем проверка ответа ИИ отличается от повторного вопроса той же модели?", "Какой вопрос об установленном порядке вы уточните до первого рабочего применения?"]))
    b += '<p class="q-hint fade">Источники практикума: Федеральный закон № 152-ФЗ (ст. 3, 5, 6, 9–12, 16, 18, 19, 21, 22); Федеральный закон № 98-ФЗ; Закон РФ № 5485-1; глава 14 Трудового кодекса РФ; NIST AI 600-1 (Generative AI Profile); Canadian Centre for Cyber Security (ITSAP.00.041). Практикум разработан для АО «Концерн ВКО „Алмаз-Антей“» (автор и преподаватель — Е. Ю. Чепик); дата обращения к источникам — 20.09.2026.</p>'
    return sec("s12", "12", "Практикум: рабочие кейсы с копируемыми запросами",
               "Дополнительный раздел: семь кейсов практикума 1.3, документ из десяти пунктов и личный чек-лист. Каждый кейс — с запросом для копирования и разбором. Используйте как отдельное занятие или выбирайте кейсы вместо основных практик.", b, "дополнительно")
